"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";
import styles from "../styles/activity-feed.module.css";

export type ActivityKind = "commit" | "comment" | "deploy" | "merge" | "alert" | "star";

export interface ActivityItem {
  /** Unique id */
  id: string;
  /** Who did it */
  actor: string;
  /** What happened (verb phrase) */
  action: string;
  /** What it happened to */
  target?: string;
  /** Icon / color category */
  kind: ActivityKind;
  /** How long ago, in minutes (deterministic — no clocks are read) */
  minutesAgo: number;
}

export interface ActivityFeedProps {
  /** Events, newest first */
  items?: ActivityItem[];
  /** Heading shown above the feed (also its accessible name) */
  title?: string;
  /** Show the heading visibly */
  showTitle?: boolean;
  /** Maximum events rendered */
  maxItems?: number;
  /** Delay between items animating in, in milliseconds */
  stagger?: number;
  /** Draw a vertical connector line between icons */
  showConnector?: boolean;
  /** Compact spacing */
  dense?: boolean;
  /** Accent color (commit icons, connector glow and focus tint) */
  accentColor?: string;
  /** Optional className merged onto the root */
  className?: string;
  /** Optional inline styles merged onto the root */
  style?: React.CSSProperties;
}

const DEFAULT_ITEMS: ActivityItem[] = [
  { id: "a1", actor: "Maya Okafor", action: "deployed", target: "web@v2.3.0 to production", kind: "deploy", minutesAgo: 2 },
  { id: "a2", actor: "Liam Chen", action: "merged pull request", target: "#482 Faster search index", kind: "merge", minutesAgo: 18 },
  { id: "a3", actor: "Sofia Martinez", action: "commented on", target: "Checkout redesign", kind: "comment", minutesAgo: 47 },
  { id: "a4", actor: "Noah Patel", action: "pushed 3 commits to", target: "feat/billing-v2", kind: "commit", minutesAgo: 95 },
  { id: "a5", actor: "Monitoring", action: "flagged elevated latency on", target: "api-eu-west", kind: "alert", minutesAgo: 260 },
  { id: "a6", actor: "Ava Thompson", action: "starred", target: "motionfoundry/ui", kind: "star", minutesAgo: 1680 },
];

const ICONS: Record<ActivityKind, React.ReactNode> = {
  commit: (
    <>
      <circle cx="12" cy="12" r="3.5" />
      <path d="M3 12h5.5M15.5 12H21" />
    </>
  ),
  comment: <path d="M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.6A8 8 0 1 1 21 12Z" />,
  deploy: <path d="M12 3c3 2 5 5.5 5 9l-2.5 3h-5L7 12c0-3.5 2-7 5-9ZM9.5 15 8 20l4-2 4 2-1.5-5M12 9.5v.01" />,
  merge: (
    <>
      <circle cx="6" cy="5" r="2" />
      <circle cx="6" cy="19" r="2" />
      <circle cx="18" cy="12" r="2" />
      <path d="M6 7v10M8 5h2a6 6 0 0 1 6 6" />
    </>
  ),
  alert: <path d="M12 4 2.5 20h19L12 4ZM12 10v4.5M12 17.5v.01" />,
  star: <path d="m12 3.5 2.6 5.3 5.9.9-4.3 4.1 1 5.8-5.2-2.7-5.2 2.7 1-5.8-4.3-4.1 5.9-.9L12 3.5Z" />,
};

function relative(min: number) {
  const m = Math.max(0, Math.round(min));
  if (m < 1) return { text: "just now", iso: "PT0M" };
  if (m < 60) return { text: `${m}m ago`, iso: `PT${m}M` };
  const h = Math.floor(m / 60);
  if (h < 24) return { text: `${h}h ago`, iso: `PT${h}H` };
  const d = Math.floor(h / 24);
  return { text: d === 1 ? "yesterday" : `${d}d ago`, iso: `P${d}D` };
}

export function ActivityFeed({
  items = DEFAULT_ITEMS,
  title = "Recent activity",
  showTitle = true,
  maxItems = 6,
  stagger = 90,
  showConnector = true,
  dense = false,
  accentColor = "#6366f1",
  className = "",
  style,
}: ActivityFeedProps) {
  const reduce = useReducedMotion();
  const id = React.useId();
  const list = items.slice(0, Math.max(1, Math.floor(maxItems)));
  const step = Math.max(0, stagger) / 1000;

  return (
    <section
      aria-labelledby={`${id}-title`}
      className={`${styles.root} ${className}`.trim()}
      data-dense={dense ? "" : undefined}
      style={{ "--mf-af-accent": accentColor, ...style } as React.CSSProperties}
    >
      <h3 id={`${id}-title`} className={showTitle ? styles.title : styles.srOnly}>
        {title}
      </h3>
      <ol className={styles.list}>
        {list.map((item, i) => {
          const t = relative(item.minutesAgo);
          const last = i === list.length - 1;
          return (
            <motion.li
              key={item.id}
              className={styles.item}
              initial={reduce ? false : { opacity: 0, x: -10 }}
              animate={{ opacity: 1, x: 0 }}
              transition={reduce ? { duration: 0 } : { duration: 0.42, delay: i * step, ease: [0.16, 1, 0.3, 1] }}
            >
              <div className={styles.rail} aria-hidden="true">
                <motion.span
                  className={styles.icon}
                  data-kind={item.kind}
                  initial={reduce ? false : { scale: 0.4 }}
                  animate={{ scale: 1 }}
                  transition={reduce ? { duration: 0 } : { type: "spring", stiffness: 520, damping: 22, delay: i * step }}
                >
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    {ICONS[item.kind]}
                  </svg>
                </motion.span>
                {showConnector && !last && (
                  <motion.span
                    className={styles.line}
                    initial={reduce ? false : { scaleY: 0 }}
                    animate={{ scaleY: 1 }}
                    transition={reduce ? { duration: 0 } : { duration: 0.4, delay: i * step + 0.15, ease: "easeOut" }}
                  />
                )}
              </div>
              <div className={styles.body}>
                <p className={styles.text}>
                  <span className={styles.actor}>{item.actor}</span> {item.action}
                  {item.target && (
                    <>
                      {" "}
                      <span className={styles.target}>{item.target}</span>
                    </>
                  )}
                </p>
                <time className={styles.time} dateTime={t.iso}>
                  {t.text}
                </time>
              </div>
            </motion.li>
          );
        })}
      </ol>
    </section>
  );
}

.root {
  --mf-af-gap: 0.875rem;
  --mf-af-icon: 2rem;
  width: 100%;
  max-width: 27rem;
  padding: 1.125rem 1.25rem 0.375rem;
  border-radius: 0.75rem;
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-surface, #141419);
  color: var(--mf-fg, #f4f4f6);
  font-size: 0.875rem;
}

.root[data-dense] {
  --mf-af-gap: 0.5rem;
  --mf-af-icon: 1.625rem;
}

.title {
  margin: 0 0 0.875rem;
  font-size: 0.9375rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.item {
  display: flex;
  gap: 0.75rem;
}

.rail {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  flex-shrink: 0;
  width: var(--mf-af-icon);
}

.icon {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--mf-af-icon);
  height: var(--mf-af-icon);
  border-radius: 999px;
  --mf-af-c: var(--mf-af-accent, #6366f1);
  color: var(--mf-af-c);
  background-color: color-mix(in srgb, var(--mf-af-c) 14%, var(--mf-surface, #141419));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--mf-af-c) 30%, transparent);
}

.root[data-dense] .icon svg {
  width: 13px;
  height: 13px;
}

.icon[data-kind="comment"] {
  --mf-af-c: #0ea5e9;
}

.icon[data-kind="deploy"] {
  --mf-af-c: #22c55e;
}

.icon[data-kind="merge"] {
  --mf-af-c: #a855f7;
}

.icon[data-kind="alert"] {
  --mf-af-c: #f59e0b;
}

.icon[data-kind="star"] {
  --mf-af-c: #eab308;
}

.line {
  flex: 1;
  width: 2px;
  min-height: 0.75rem;
  margin: 0.25rem 0;
  border-radius: 2px;
  background: linear-gradient(
    to bottom,
    color-mix(in srgb, var(--mf-af-accent, #6366f1) 45%, var(--mf-border, #2e2e38)),
    var(--mf-border, #2e2e38)
  );
  transform-origin: top;
}

.body {
  flex: 1;
  min-width: 0;
  padding: 0.25rem 0 var(--mf-af-gap);
}

.root[data-dense] .body {
  padding-top: 0.125rem;
}

.text {
  margin: 0;
  line-height: 1.45;
  color: var(--mf-muted, #a1a1aa);
}

.actor {
  font-weight: 600;
  color: var(--mf-fg, #f4f4f6);
}

.target {
  font-weight: 500;
  color: var(--mf-fg, #f4f4f6);
}

.time {
  display: block;
  margin-top: 0.125rem;
  font-size: 0.75rem;
  color: var(--mf-subtle, #71717a);
  font-variant-numeric: tabular-nums;
}

.root[data-dense] .time {
  display: inline;
  margin: 0 0 0 0.375rem;
}

.root[data-dense] .text {
  display: inline;
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .line,
  .icon {
    transition: none;
    animation: none;
  }
}

