"use client";

import { motion } from "motion/react";

const items = [
  { id: 1, actor: "Maya Okafor", action: "deployed", target: "web@v2.3.0", time: "2m ago", color: "text-emerald-500 bg-emerald-500/15" },
  { id: 2, actor: "Liam Chen", action: "merged", target: "#482 Faster search", time: "18m ago", color: "text-purple-500 bg-purple-500/15" },
  { id: 3, actor: "Sofia Martinez", action: "commented on", target: "Checkout redesign", time: "47m ago", color: "text-sky-500 bg-sky-500/15" },
  { id: 4, actor: "Noah Patel", action: "pushed to", target: "feat/billing-v2", time: "1h ago", color: "text-indigo-500 bg-indigo-500/15" },
];

export function ActivityFeedTailwind() {
  return (
    <section aria-labelledby="feed-title" className="w-full max-w-md rounded-xl border border-zinc-800 bg-zinc-900 p-5 text-sm">
      <h3 id="feed-title" className="mb-3 font-semibold text-zinc-100">Recent activity</h3>
      <ol>
        {items.map((it, i) => (
          <motion.li key={it.id} initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.09 }} className="flex gap-3">
            <div aria-hidden className="flex flex-col items-center">
              <span className={`grid size-8 place-items-center rounded-full ${it.color}`}>●</span>
              {i < items.length - 1 && <span className="my-1 w-0.5 flex-1 rounded bg-zinc-800" />}
            </div>
            <div className="pb-3.5 pt-1">
              <p className="text-zinc-400"><span className="font-semibold text-zinc-100">{it.actor}</span> {it.action} <span className="font-medium text-zinc-100">{it.target}</span></p>
              <time className="text-xs text-zinc-500">{it.time}</time>
            </div>
          </motion.li>
        ))}
      </ol>
    </section>
  );
}
